  /*
   * pax_wr()
   *  write a pax header for the file specified in the ARCHD to the archive
   *  Have to check for file types that cannot be stored and file names that
   *  are too long. Be careful of the term (last arg) to ul_oct, we only use
   *  '\0' for the termination character (this is different than picky tar)
   *  ASSUMED: space after header in header block is zero filled
   * Return:
   *  0 if file has data to be written after the header, 1 if file has NO
   *  data to write after the header, -1 if archive write failed
   */

  func wr(_ arcn : ARCHD) -> Result {
/*    HD_USTAR *hd;
    char *pt;
    char hdblk[sizeof(HD_USTAR)];
    mode_t mode12only;
    term_char=1;    /* To pass conformance tests 274, 301 */
    char size_value[100];
    bzero(size_value, sizeof(size_value));
*/
    var term_char = OctalTerminator._3 // original setting

    /*
     * check for those file system types pax cannot store
     */
    if arcn.type == .SCK {
      Tty.paxwarn(true, "Pax cannot archive a socket \(arcn.org_name)")
      return .partial
    }

        var hd = HD_USTAR()

    /*
     * check the length of the linkname
     */
    if (((arcn.type == .SLK) || (arcn.type == .HLK) ||
         (arcn.type == .HRG)) && (arcn.ln_name.count > MemoryLayout.size(ofValue: hd.linkname))) {
      Tty.paxwarn(true, "Link name too long for pax \(arcn.ln_name)")
      /*
       * Conformance: test pax:285 wants error code to be non-zero, and
       * test tar:12 wants error code from pax to be 0
       */
      return .partial
    }

    /*
     * split the path name into prefix and name fields (if needed). if
     * pt != arcn.name, the name has to be split
     */
    let nam = name_split(arcn.name)
    guard let nam else {
      Tty.paxwarn(true, "File name too long for pax \(arcn.name)")
      return .partial
    }

    generate_pax_ext_header_and_data(arcn, global_ext_header_inx, global_ext_header_entry, .PAXGTYPE, header_name_g, header_name_g_requested);
    generate_pax_ext_header_and_data(arcn, ext_header_inx, ext_header_entry, .PAXXTYPE, header_name_x, header_name_x_requested);

    /*
     * zero out the header so we don't have to worry about zero fill below
     */

    arcn.pad = 0
    /* To pass conformance tests 274/301, always set these fields to "zero" */
    withUnsafeMutableBytes(of: &hd.devmajor) { $0.copyBytes(from: ul_oct(0, $0.count, term_char)!.utf8) }
    withUnsafeMutableBytes(of: &hd.devminor) { $0.copyBytes(from: ul_oct(0, $0.count, term_char)!.utf8) }

    /*
     * split the name, or zero out the prefix
     */

    /*
       * name was split, pt points at the / where the split is to
       * occur, we remove the / and copy the first part to the prefix
       */
      withUnsafeMutableBytes(of: &hd.prefix) { $0.copyBytes(from: nam.utf8) }

    /*
     * copy the name part. this may be the whole path or the part after
     * the prefix
     */
    var pt = Array(arcn.name.dropFirst(name.count).utf8)
    if pt.count < MemoryLayout.size(ofValue: hd.name) { pt.append(0) }
    withUnsafeMutableBytes(of: &hd.name) { $0.copyBytes(from: pt) }

    var dowarn = true

    defer {
      /*
       * header field is out of range
       */
      if dowarn {
        Tty.paxwarn(true, "Pax header field is too small for \(arcn.org_name)")
      }

    }

    /*
     * set the fields in the header that are type dependent
     */
    switch (arcn.type) {
      case .DIR:
        hd.typeflag = TarFileType.DIRTYPE.rawValue.asciiValue!
        guard let tt = ul_oct(0, MemoryLayout.size(ofValue: hd.size), term_char) else {
          return .partial
