          }
          $0.copyBytes(from: j)
        }
        withUnsafeMutableBytes(of: &hd.size) { $0.copyBytes(from:  ul_oct(0, $0.count, term_char)!.utf8 ) }
        break
      case .REG, .CTG:
        fallthrough
      default:
        /*
         * file data with this type, set the padding
         */
        if (arcn.type == .CTG) {
          hd.typeflag = TarFileType.CONTTYPE.rawValue.asciiValue!
        }
        else {
          hd.typeflag = TarFileType.REGTYPE.rawValue.asciiValue!
        }
        arcn.pad = TAR_PAD(arcn.sb.size);
        let z = ul_oct(arcn.sb.size, MemoryLayout.size(ofValue: hd.size), term_char)
        if let z {
          withUnsafeMutableBytes(of: &hd.size) { $0.copyBytes(from: z.utf8) }
        } else {
          /*
           * Insert an extended header for size=<arcn.sb.st_size> since
           * octal range of 12 byte string cannot fit > 8GiB files in header.
           * This fixes Conformance test pax.343
           */
          let size_value = String(arcn.sb.size)
          for i in 0..<o_option_table.count {
            if size_header_name == o_option_table[i].name {
              let size_x = size_value
              ext_header_entry[ext_header_inx] = i
              ext_header_inx += 1
            }
          }
          generate_pax_ext_header_and_data(arcn, ext_header_inx, &ext_header_entry[0], .PAXXTYPE, header_name_x, header_name_x_requested)
        }
        break
    }

    // WARNING: hd.magic needs to be the same size (or larger) than TMAGIC
    withUnsafeMutableBytes(of: &hd.magic) { $0.copyBytes(from: TMAGIC.utf8) }     // strncpy(&hd.magic, TMAGIC, Int(TMAGLEN))
    withUnsafeMutableBytes(of: &hd.version) { $0.copyBytes(from: TVERSION.utf8) } //  strncpy(&hd.version, TVERSION, Int(TVERSLEN))

    /*
     * set the remaining fields. Some versions want all 16 bits of mode
     * we better humor them (they really do not meet spec though)....
     */
    if let uu = ul_oct(arcn.sb.userId, MemoryLayout.size(ofValue: hd.uid), term_char) {
      withUnsafeMutableBytes(of: &hd.uid) { $0.copyBytes(from: uu.utf8) }
    } else {
      if uid_nobody == nil {
        uid_nobody = cache.uid_name("nobody")
        if uid_nobody == nil {
          return .partial
        }
      }
      if uid_warn != arcn.sb.userId {
        uid_warn = arcn.sb.userId
        Tty.paxwarn(true, "Pax header field is too small for uid \(arcn.sb.userId), using nobody")
      }
      if let uuu = ul_oct(uid_nobody!, MemoryLayout.size(ofValue: hd.uid), term_char) {
        withUnsafeMutableBytes(of: &hd.uid) { $0.copyBytes(from: uuu.utf8) }
      } else {
        return .partial
      }
    }
    if let gg = ul_oct(arcn.sb.groupId, MemoryLayout.size(ofValue: hd.gid), term_char) {
      withUnsafeMutableBytes(of: &hd.gid) { $0.copyBytes(from: gg.utf8) }
    } else {
      if (gid_nobody == nil) {
        gid_nobody = cache.gid_name("nobody")
        if gid_nobody == nil {
          return .partial
        }
      }
      if gid_warn != arcn.sb.groupId {
        gid_warn = arcn.sb.groupId
        Tty.paxwarn(true, "Pax header field is too small for gid \(arcn.sb.groupId), using nobody")
      }
      if let ggg = ul_oct(gid_nobody!, MemoryLayout.size(ofValue: hd.gid), term_char) {
        withUnsafeMutableBytes(of: &hd.gid) { $0.copyBytes(from: ggg.utf8) }
      } else {
        return .partial
      }
    }
    /* However, Unix conformance tests do not like MORE than 12 mode bits:
     remove all beyond (see definition of stat.st_mode structure)    */
    let mode12only = arcn.sb.permissions.rawValue
    withUnsafeMutableBytes(of: &hd.mode) { $0.copyBytes(from: ul_oct( UInt(mode12only), $0.count, term_char)!.utf8) }
    withUnsafeMutableBytes(of: &hd.mtime) { $0.copyBytes(from: ul_oct( UInt(arcn.sb.lastModified.secs), $0.count,term_char)!.utf8 ) }
//      return .partial

    withUnsafeMutableBytes(of: &hd.uname) { $0.copyBytes(from: cache.name_uid(arcn.sb.userId, false).utf8) }
    withUnsafeMutableBytes(of: &hd.gname) { $0.copyBytes(from: cache.name_gid(arcn.sb.groupId, false).utf8) }

    /*
     * calculate and store the checksum write the header to the archive
     * return 0 tells the caller to now write the file data, 1 says no data
     * needs to be written
     */
      let ck = withUnsafeBytes(of: hd) { pax_chksm( Array($0) ) }
      withUnsafeMutableBytes(of: &hd.chksum) { $0.copyBytes(from: ul_oct(ck, $0.count, term_char)!.utf8) }

    dowarn = false
      if (wr_rdbuf(hdblk, MemoryLayout<HD_USTAR>.size) < 0) {
      return .failed;
    }
      if (wr_skip(BLKMULT - MemoryLayout<HD_USTAR>.size) < 0) {
      return .failed;
    }
    if ((arcn.type == .CTG) || (arcn.type == .REG)) {
      return .ok
    }
    return .partial
  }

  /*
   * name_split()
   *  see if the name has to be split for storage in a ustar header. We try
   *  to fit the entire name in the name field without splitting if we can.
   *  The split point is always at a /
   * Return
   *  character pointer to split point (always the / that is to be removed
   *  if the split is not needed, the points is set to the start of the file
   *  name (it would violate the spec to split there). A NULL is returned if
   *  the file name is too long
   */

  // Deals with Unicode strings
  func name_split(_ namex : String) -> String? {

    /*
     * check to see if the file name is small enough to fit in the name
     * field. if so just return a pointer to the name.
     */

    let name = ArraySlice(namex.utf8)

    let len2 = name.count
    if len2 <= TNMSZ { return namex }
    if len2 > TPFSZ + TNMSZ { return nil }

    /*
     * we start looking at the biggest sized piece that fits in the name
     * field. We walk forward looking for a slash to split at. The idea is
     * to find the biggest piece to fit in the name field (or the smallest
     * prefix we can find)
     */
    var start = name.dropFirst(len2 - TNMSZ - 1)
    let slash = "/".utf8.first!
    if start.first == slash && start == name { start = start.dropFirst() }  /* 101 byte paths with leading "/" are dinged otherwise */
    start = start.drop { $0 != slash }

    /*
     * if we hit the end of the string, this name cannot be split, so we
     * cannot store this file.
     */
    if start.isEmpty { return nil }

    let len = name.count - start.count

    /*
     * NOTE: /str where the length of str == TNMSZ can not be stored under
     * the p1003.1-1990 spec for ustar. We could force a prefix of / and
     * the file would then expand on extract to //str. The len == 0 below
     * makes this special case follow the spec to the letter.
     */
    if len >= TPFSZ || len == 0 { return nil }

    /*
     * ok have a split point, return it to the caller
     */
    return String(decoding: name.prefix(len), as: UTF8.self)
  }

  func major(_ x : UInt) -> UInt {
    return (x >> 24) & 0xff
  }

  func minor(_ x : UInt) -> UInt {
    return x & 0xffffff
  }
